from taf.hw.mcs.devices.hbte.hbte import HBTE
from taf.hw.mcs.exception import InputIdInvalid


class HBTEPPSAM6416233890053601A(HBTE):

    _vendor = "HBTE"
    _model = 'PPSAM-64X16-2.3-3.8-90-0.5-360-1-A'
    _version = None

    def __init__(self, **kwargs):
        super(HBTEPPSAM6416233890053601A, self).__init__(**kwargs)
        self._port_num_in_group = int(self.row_num / 4)

    def _get_polar_group_index_by_input_id(self, input_id):
        return int((input_id - 1) / 2) % 8

    def _get_row_group_index_by_input_id(self, input_id):
        return int((input_id - 1) / self._port_num_in_group)

    def _get_input_ids_by_group_id(self, input_group_id):
        if input_group_id is None or input_group_id not in range(1, int(self.row_num / 2) + 1):
            raise InputIdInvalid(input_group_id)
        return [input_group_id * 2 - 1, input_group_id * 2]
